import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type StarWarsCrawlProps = Record<string, any>;

// Helper for generating deterministic stars based on a seed (simple index here)
const StarField: React.FC<{ count: number; width: number; height: number }> = React.memo(({ count, width, height }) => {
  const stars = React.useMemo(() => {
    return new Array(count).fill(0).map((_, i) => ({
      x: (Math.sin(i * 12.9898) * 43758.5453 % 1 + 1) / 2 * width, // Pseudo-random
      y: (Math.cos(i * 34.234) * 23423.534 % 1 + 1) / 2 * height,
      size: Math.random() * 2 + 1,
      opacity: Math.random() * 0.5 + 0.3,
    }));
  }, [count, width, height]);

  return (
    <AbsoluteFill>
      {stars.map((star, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: star.x,
            top: star.y,
            width: star.size,
            height: star.size,
            backgroundColor: "white",
            opacity: star.opacity,
            borderRadius: "50%",
          }}
        />
      ))}
    </AbsoluteFill>
  );
});

const StarWarsCrawl: React.FC<StarWarsCrawlProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 60,
  introText = "A long time ago in a galaxy far, far away....",
  logoText = "STAR WARS",
  episodeTitle = "Episode IV",
  episodeSubtitle = "A NEW HOPE",
  crawlBody = "It is a period of civil war. Rebel spaceships, striking from a hidden base, have won their first victory against the evil Galactic Empire.\n\nDuring the battle, Rebel spies managed to steal secret plans to the Empire's ultimate weapon, the DEATH STAR, an armored space station with enough power to destroy an entire planet.\n\nPursued by the Empire's sinister agents, Princess Leia races home aboard her starship, custodian of the stolen plans that can save her people and restore freedom to the galaxy....",
  starCount = 200,
  accentColor = "#FFE81F",
}) => {
  useFontLoader(["Pathway Gothic One", "Anton", "News Cycle"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- TIMING CONSTANTS ---
  const INTRO_DURATION = 5 * fps;
  const LOGO_START = INTRO_DURATION;
  const LOGO_DURATION = 7 * fps; // Logo visible for 7 seconds
  const LOGO_END = LOGO_START + LOGO_DURATION;
  const CRAWL_START = LOGO_START + (2 * fps); // Crawl starts slightly after logo appears
  const CRAWL_DURATION = (durationInSeconds * fps) - CRAWL_START;

  // --- ANIMATIONS ---

  // 1. Intro Text ("A long time ago...")
  const introOpacity = interpolate(
    frame,
    [0, 1 * fps, 3.5 * fps, 4.5 * fps],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 2. Main Logo ("STAR WARS")
  const logoScale = interpolate(
    frame,
    [LOGO_START, LOGO_END],
    [1.5, 0.05], // Shrinks into distance
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  const logoOpacity = interpolate(
    frame,
    [LOGO_START, LOGO_END - 10, LOGO_END],
    [1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. The Crawl
  // Calculate vertical movement. We want it to start below screen and end far above.
  // The 'top' position moves from 100% height to roughly -200% height (deep into space)
  const crawlProgress = interpolate(
    frame - CRAWL_START,
    [0, CRAWL_DURATION],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Start at bottom (height), move upwards.
  // We need to move enough pixels to clear the text length plus some extra for the "distance" effect.
  // A rough estimation is usually fine, or we can use percentages.
  // Using a very large negative value to simulate vanishing into infinity.
  const crawlOffset = interpolate(
    frame - CRAWL_START,
    [0, CRAWL_DURATION],
    [height * 0.8, -height * 2.5], 
    { extrapolateLeft: "clamp" } // Let it continue if duration is long
  );

  const crawlOpacity = interpolate(
      frame - CRAWL_START,
      [0, 15, CRAWL_DURATION - (5 * fps), CRAWL_DURATION],
      [0, 1, 1, 0], // Fade in slightly at start, fade out at very end
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );


  // Render
  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background Stars */}
      <StarField count={starCount} width={width} height={height} />

      {/* 1. Intro Text Layer */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          opacity: introOpacity,
          zIndex: 10,
        }}
      >
        <h1
          style={{
            fontFamily: "'Pathway Gothic One', sans-serif",
            color: "#4BD5EE", // Classic Star Wars blue for intro
            fontSize: width * 0.045,
            fontWeight: 400,
            textAlign: "left",
            margin: 0,
            lineHeight: 1.5,
            width: width * 0.7,
          }}
        >
          {introText}
        </h1>
      </AbsoluteFill>

      {/* 2. Logo Layer */}
      {frame > LOGO_START && (
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            opacity: logoOpacity,
            transform: `scale(${logoScale})`,
            zIndex: 20,
          }}
        >
          <h1
            style={{
              fontFamily: "'Anton', sans-serif", // Thick font
              color: "transparent",
              WebkitTextStroke: `${width * 0.005}px ${accentColor}`, // Hollow yellow text
              fontSize: width * 0.15, // Huge
              textAlign: "center",
              lineHeight: 1,
              margin: 0,
              textShadow: "0 0 0px rgba(0,0,0,0)", // Clean edges
            }}
          >
            {logoText}
          </h1>
        </AbsoluteFill>
      )}

      {/* 3. Crawl Layer */}
      {frame > CRAWL_START && (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            perspective: `${height * 0.6}px`, // Adjusted perspective for the angle
            overflow: "hidden",
            zIndex: 5,
            opacity: crawlOpacity,
          }}
        >
          <div
            style={{
              position: "absolute",
              top: 0,
              left: "15%", // Center horizontally with margins
              width: "70%",
              height: "200%", // Extra height to allow scrolling
              transformOrigin: "50% 100%",
              transform: `rotateX(25deg) translateY(${crawlOffset}px)`,
              textAlign: "justify",
            }}
          >
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                textAlign: "center",
                color: accentColor,
                fontFamily: "'News Cycle', sans-serif",
                fontWeight: "bold",
              }}
            >
              <h2
                style={{
                  fontSize: width * 0.05,
                  margin: `0 0 ${height * 0.01}px 0`,
                  fontWeight: 400,
                  letterSpacing: "0.1em",
                }}
              >
                {episodeTitle}
              </h2>
              <h1
                style={{
                  fontSize: width * 0.08,
                  margin: `0 0 ${height * 0.05}px 0`,
                  textTransform: "uppercase",
                  lineHeight: 1.1,
                }}
              >
                {episodeSubtitle}
              </h1>
              <div
                style={{
                  fontSize: width * 0.05,
                  lineHeight: 1.5,
                  textAlign: "justify",
                  whiteSpace: "pre-wrap",
                  paddingBottom: height, // Add padding at bottom so text clears completely
                }}
              >
                {crawlBody}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Vignette for depth (fades edges) */}
      <AbsoluteFill
        style={{
            background: "radial-gradient(circle, rgba(0,0,0,0) 60%, rgba(0,0,0,1) 100%)",
            pointerEvents: "none",
            zIndex: 50,
        }}
      />
    </AbsoluteFill>
  );
};

export default StarWarsCrawl;